uint64_t encrypt_2_rounds_forward(uint64_t plaintext, uint32_t k0, uint32_t k1) {
    uint32_t k0_exp = expand(k0 & 0xFFFFF);
    uint32_t k1_exp = expand(k1 & 0xFFFFF);

