#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

uint32_t expand(uint32_t key) {
    return key ^ (key << 16) ^ (key * 12345);
}

uint8_t g_function(uint8_t a, uint8_t b, uint8_t x) {
    uint8_t temp = (a + b + x) & 0xFF;
    return ((temp << 2) | (temp >> 6)) & 0xFF;
}

uint32_t f_function(uint32_t input_val) {
    uint8_t x[4];
    uint8_t y[4];

    for (int i = 0; i < 4; i++) {
        x[i] = input_val & 0xFF;
        input_val >>= 8;
    }

    y[2] = g_function(x[3] ^ x[2], x[1] ^ x[0], 1);
    y[3] = g_function(x[3], y[2], 0);
    y[1] = g_function(x[1] ^ x[0], y[2], 0);
    y[0] = g_function(x[0], y[1], 1);

    uint32_t output = 0;
    for (int i = 0; i < 4; i++) {
        output |= (uint32_t)y[i] << (8 * i);
    }

    return output & 0xFFFFFFFF;
}

uint32_t getleft(uint64_t x) {
    return (x >> 32) & 0xFFFFFFFF;
}

uint32_t getright(uint64_t x) {
    return x & 0xFFFFFFFF;
}

uint64_t merge(uint32_t left, uint32_t right) {
    return ((uint64_t)(left & 0xFFFFFFFF) << 32) | (right & 0xFFFFFFFF);
}

// Forward 2 rounds
uint64_t forward_2rounds(uint64_t plaintext, uint32_t k0, uint32_t k1) {
    uint32_t k0_exp = expand(k0 & 0xFFFFF);
    uint32_t k1_exp = expand(k1 & 0xFFFFF);

    uint32_t left = getleft(plaintext);
    uint32_t right = getright(plaintext);

    right ^= left;

    for (int r = 0; r < 2; r++) {
        uint32_t mixed = f_function(right ^ (r == 0 ? k0_exp : k1_exp));
        uint32_t temp = right;
        right = left ^ mixed;
        left = temp;
    }

    return merge(left, right);
}

// Backward 2 rounds
uint64_t backward_2rounds(uint64_t ciphertext, uint32_t k2, uint32_t k3) {
    uint32_t k2_exp = expand(k2 & 0xFFFFF);
    uint32_t k3_exp = expand(k3 & 0xFFFFF);

    uint32_t left = getright(ciphertext);
    uint32_t right = getleft(ciphertext);

    left ^= right;

    for (int r = 1; r >= 0; r--) {
        uint32_t temp = left;
        left = right;
        uint32_t mixed = f_function(temp ^ (r == 1 ? k3_exp : k2_exp));
        right = temp;
        left ^= mixed;
    }

    return merge(left, right);
}

uint64_t encrypt_full(uint64_t plaintext, uint32_t k0, uint32_t k1, uint32_t k2, uint32_t k3) {
    uint32_t key[4] = {expand(k0 & 0xFFFFF), expand(k1 & 0xFFFFF), expand(k2 & 0xFFFFF), expand(k3 & 0xFFFFF)};

    uint32_t left = getleft(plaintext);
    uint32_t right = getright(plaintext);

    right ^= left;

    for (int r = 0; r < 4; r++) {
        uint32_t mixed = f_function(right ^ key[r]);
        uint32_t temp = right;
        right = left ^ mixed;
        left = temp;
    }

    left ^= right;

    return merge(right, left);
}

#define NUM_PAIRS 32
#define HASH_SIZE (1 << 20)

uint64_t plaintexts[NUM_PAIRS];
uint64_t ciphertexts[NUM_PAIRS];

typedef struct {
    uint64_t value;
    uint32_t k0;
    uint32_t k1;
    struct node *next;
} HashNode;

HashNode *hash_table[HASH_SIZE];

uint32_t hash_func(uint64_t value) {
    return (value ^ (value >> 32)) % HASH_SIZE;
}

void hash_insert(uint64_t value, uint32_t k0, uint32_t k1) {
    uint32_t h = hash_func(value);
    HashNode *node = (HashNode *)malloc(sizeof(HashNode));
    node->value = value;
    node->k0 = k0;
    node->k1 = k1;
    node->next = hash_table[h];
    hash_table[h] = node;
}

void hash_lookup(uint64_t value, uint32_t k2, uint32_t k3) {
    uint32_t h = hash_func(value);
    for (HashNode *node = hash_table[h]; node; node = node->next) {
        if (node->value == value) {
            uint32_t k0 = node->k0;
            uint32_t k1 = node->k1;

            // Verify against all pairs
            int all_match = 1;
            for (int j = 0; j < NUM_PAIRS; j++) {
                if (encrypt_full(plaintexts[j], k0, k1, k2, k3) != ciphertexts[j]) {
                    all_match = 0;
                    break;
                }
            }

            if (all_match) {
                printf("\n=== KEY FOUND ===\n");
                printf("k0 = 0x%05X\n", k0);
                printf("k1 = 0x%05X\n", k1);
                printf("k2 = 0x%05X\n", k2);
                printf("k3 = 0x%05X\n", k3);
                exit(0);
            }
        }
    }
}

int main() {
    FILE *fp = fopen("/app/pairs.txt", "r");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open pairs.txt\n");
        return 1;
    }

    for (int i = 0; i < NUM_PAIRS; i++) {
        if (fscanf(fp, "%lu %lu", &plaintexts[i], &ciphertexts[i]) != 2) {
            fprintf(stderr, "Error: Cannot read pair %d\n", i);
            return 1;
        }
    }
    fclose(fp);

    printf("Starting meet-in-the-middle attack...\n");

    // Initialize hash table
    for (int i = 0; i < HASH_SIZE; i++) {
        hash_table[i] = NULL;
    }

    // Build forward table from first plaintext
    printf("Building forward table...\n");
    for (uint32_t k0 = 0; k0 < (1U << 20); k0++) {
        if ((k0 & 0x3FFF) == 0) {
            printf("  k0 = 0x%05X\n", k0);
        }

        for (uint32_t k1 = 0; k1 < (1U << 20); k1++) {
            uint64_t forward_val = forward_2rounds(plaintexts[0], k0, k1);
            hash_insert(forward_val, k0, k1);
        }
    }

    printf("\nSearching backward from first ciphertext...\n");

    // Search backward from ciphertext
    for (uint32_t k3 = 0; k3 < (1U << 20); k3++) {
        if ((k3 & 0x3FFF) == 0) {
            printf("  k3 = 0x%05X\n", k3);
        }

        for (uint32_t k2 = 0; k2 < (1U << 20); k2++) {
            uint64_t backward_val = backward_2rounds(ciphertexts[0], k2, k3);
            hash_lookup(backward_val, k2, k3);
        }
    }

    printf("Key not found\n");
    return 1;
}

