#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint64_t intermediate;
    uint32_t k0, k1;
} Entry;

uint64_t pairs[32][2];

static inline uint32_t getleft(uint64_t x) { return x >> 32; }
static inline uint32_t getright(uint64_t x) { return (uint32_t)x; }
static inline uint64_t merge(uint32_t l, uint32_t r) { return ((uint64_t)l << 32) | r; }

static inline uint32_t expand(uint32_t k) {
    return k ^ (k << 16) ^ (k * 12345);
}

static inline uint8_t g(uint8_t a, uint8_t b, uint8_t x) {
    uint8_t t = (a + b + x);
    return (t << 2) | (t >> 6);
}

static inline uint32_t f_func(uint32_t in) {
    uint8_t x0 = in, x1 = in >> 8, x2 = in >> 16, x3 = in >> 24;
    uint8_t y2 = g(x3 ^ x2, x1 ^ x0, 1);
    uint8_t y3 = g(x3, y2, 0);
    uint8_t y1 = g(x1 ^ x0, y2, 0);
    uint8_t y0 = g(x0, y1, 1);
    return y0 | ((uint32_t)y1 << 8) | ((uint32_t)y2 << 16) | ((uint32_t)y3 << 24);
}

uint64_t forward_2r(uint64_t pt, uint32_t ek0, uint32_t ek1) {
    uint32_t L = getleft(pt), R = getright(pt);
    R ^= L;

    uint32_t F = f_func(R ^ ek0);
    uint32_t T = R;
    R = L ^ F;
    L = T;

    F = f_func(R ^ ek1);
    T = R;
    R = L ^ F;
    L = T;

    return merge(L, R);
}

uint64_t backward_2r(uint64_t ct, uint32_t ek2, uint32_t ek3) {
    uint32_t L = getright(ct), R = getleft(ct);
    L ^= R;

    uint32_t T = L;
    L = R;
    uint32_t F = f_func(T ^ ek3);
    R = T;
    L ^= F;

    T = L;
    L = R;
    F = f_func(T ^ ek2);
    R = T;
    L ^= F;

    return merge(L, R);
}

uint64_t enc_full(uint64_t pt, uint32_t e0, uint32_t e1, uint32_t e2, uint32_t e3) {
    uint32_t L = getleft(pt), R = getright(pt);
    R ^= L;

    #define RND(ek) { uint32_t F = f_func(R ^ ek); uint32_t T = R; R = L ^ F; L = T; }
    RND(e0); RND(e1); RND(e2); RND(e3);
    #undef RND

    L ^= R;
    return merge(R, L);
}

