    printf("Meet-in-the-middle attack (file-based)\n");
    printf("Phase 1: Building forward table...\n");

    FILE *fwd = fopen("/tmp/forward.bin", "wb");
    if (!fwd) return 1;

    long entries = 0;
    for (uint32_t k0 = 0; k0 < (1U << 18); k0++) {
        if ((k0 & 0xFF) == 0) printf("  k0=0x%05X\n", k0);
        uint32_t ek0 = expand(k0);

        for (uint32_t k1 = 0; k1 < (1U << 20); k1++) {
