#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define NUM_PAIRS 32
#define MAX_K (1U << 20)

uint64_t pairs[NUM_PAIRS][2];

static inline int parity(uint64_t x) {
    x ^= x >> 32;
    x ^= x >> 16;
    x ^= x >> 8;
    x ^= x >> 4;
    x ^= x >> 2;
    x ^= x >> 1;
    return x & 1;
}

static inline int bit_parity(uint64_t x, int start, int end) {
    uint64_t mask = 0;
    for (int i = start; i < end && i < 64; i++) {
        mask |= (1UL << i);
    }
    return parity(x & mask);
}

static inline uint32_t expand(uint32_t k) {
    return k ^ (k << 16) ^ (k * 12345);
}

int main() {
    FILE *fp = fopen("/app/pairs.txt", "r");
    if (!fp) return 1;
    for (int i = 0; i < NUM_PAIRS; i++) {
        fscanf(fp, "%lu %lu", &pairs[i][0], &pairs[i][1]);
    }
    fclose(fp);

    printf("Comprehensive linear cryptanalysis on FEAL-4\n");
    printf("Searching for expanded keys with significant parity biases...\n\n");

    int best_matches = 0;
    uint32_t best_ek[4] = {0, 0, 0, 0};
    double best_bias = 0;

    // Try limited search for expanded_key values
    printf("Phase 1: Finding biased expanded keys...\n");

    for (uint32_t ek_test = 0; ek_test < (1U << 16); ek_test++) {
        if ((ek_test & 0xFF) == 0) {
            printf("  Testing ek=0x%08X...\n", ek_test);
        }

        // Try this as expanded_key[0]
        int count_match = 0, count_total = 0;

        for (int i = 0; i < NUM_PAIRS; i++) {
            uint64_t P = pairs[i][0];
            uint64_t C = pairs[i][1];

            // Test various linear approximations involving P, C, and ek_test
            // LA: parity(certain bits of P) XOR parity(certain bits of C) XOR parity(certain bits of ek) = 0?

            // Try different bit selections
            int p_bits = parity(P);  // All bits
            int c_bits = parity(C);
            int k_bits = parity(ek_test);
            int eq1 = (p_bits ^ c_bits ^ k_bits) == 0;

            int p_high = bit_parity(P, 32, 64);  // High 32 bits
            int c_high = bit_parity(C, 32, 64);
            int k_high = parity(ek_test >> 16);
            int eq2 = (p_high ^ c_high ^ k_high) == 0;

            int p_low = bit_parity(P, 0, 32);  // Low 32 bits
            int c_low = bit_parity(C, 0, 32);
            int k_low = parity(ek_test & 0xFFFF);
            int eq3 = (p_low ^ c_low ^ k_low) == 0;

            if (eq1 || eq2 || eq3) {
                count_match++;
            }
            count_total++;
        }

        double bias = (double)abs(count_match - (count_total >> 1)) / count_total;
        if (bias > best_bias) {
            best_bias = bias;
            best_matches = count_match;
            best_ek[0] = ek_test;

            if (bias > 0.2) {
                printf("    Promising ek: 0x%08X bias: %.3f matches: %d/%d\n",
                       ek_test, bias, count_match, count_total);
            }
        }
    }

    printf("\nBest found: ek0=0x%08X with bias %.3f (%d/%d matches)\n",
           best_ek[0], best_bias, best_matches, NUM_PAIRS);

    // For computational feasibility, we would continue the analysis for ek1, ek2, ek3
    // and use the constraints to narrow down the full key space
    printf("\nLinear cryptanalysis phase complete.\n");
    printf("A full implementation would continue to:\n");
    printf("  1. Recover biased patterns for all 4 round keys\n");
    printf("  2. Use constraint solving to find keys matching multiple approximations\n");
    printf("  3. Verify candidates against all known pairs\n");

    return 1;
}

