#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define NPAIRS 32

uint64_t P[NPAIRS], C[NPAIRS];  // Pairs
uint32_t EK_CACHE[1<<20];       // Expand cache

static inline uint32_t getleft(uint64_t x) { return x >> 32; }
static inline uint32_t getright(uint64_t x) { return (uint32_t)x; }
static inline uint64_t merge(uint32_t l, uint32_t r) { return ((uint64_t)l << 32) | r; }

static inline uint32_t expand(uint32_t k) {
    return k ^ (k << 16) ^ (k * 12345);
}

static inline uint8_t g(uint8_t a, uint8_t b, uint8_t x) {
    uint8_t t = (a + b + x);
    return (t << 2) | (t >> 6);
}

static inline uint32_t f_func(uint32_t in) {
    uint8_t x0 = in, x1 = in >> 8, x2 = in >> 16, x3 = in >> 24;
    uint8_t y2 = g(x3 ^ x2, x1 ^ x0, 1);
    uint8_t y3 = g(x3, y2, 0);
    uint8_t y1 = g(x1 ^ x0, y2, 0);
    uint8_t y0 = g(x0, y1, 1);
    return y0 | ((uint32_t)y1 << 8) | ((uint32_t)y2 << 16) | ((uint32_t)y3 << 24);
}

static inline uint64_t encrypt(uint64_t pt, uint32_t ek0, uint32_t ek1, uint32_t ek2, uint32_t ek3) {
    uint32_t L = getleft(pt), R = getright(pt);
    R ^= L;

    uint32_t F = f_func(R ^ ek0);
    uint32_t T = R;
    R = L ^ F;
    L = T;

    F = f_func(R ^ ek1);
    T = R;
    R = L ^ F;
    L = T;

    F = f_func(R ^ ek2);
    T = R;
    R = L ^ F;
    L = T;

    F = f_func(R ^ ek3);
    T = R;
    R = L ^ F;
    L = T;

    L ^= R;
    return merge(R, L);
}

int check_key(uint32_t ek0, uint32_t ek1, uint32_t ek2, uint32_t ek3) {
    // Quick check: only test first 3 pairs for speed
    for (int i = 0; i < 3; i++) {
        if (encrypt(P[i], ek0, ek1, ek2, ek3) != C[i]) return 0;
    }
    // Full check
    for (int i = 3; i < NPAIRS; i++) {
        if (encrypt(P[i], ek0, ek1, ek2, ek3) != C[i]) return 0;
    }
    return 1;
}

int main() {
    FILE *fp = fopen("/app/pairs.txt", "r");
    if (!fp) return 1;
    for (int i = 0; i < NPAIRS; i++) {
        fscanf(fp, "%lu %lu", &P[i], &C[i]);
    }
    fclose(fp);

    printf("Building expand cache...\n");
    #pragma omp parallel for
    for (int i = 0; i < (1 << 20); i++) {
        EK_CACHE[i] = expand(i);
    }

    printf("Starting optimized brute force (estimated 2^80 keys)...\n");
    printf("Note: This will search until key is found or time limit exceeded.\n\n");

    long long checked = 0;
    long long start_time = time(NULL);

    // Reduced search space version - test all combinations for k0 in [0, 2^16)
    // This gives 2^76 total combinations which might complete
    #pragma omp parallel for collapse(4) schedule(dynamic) reduction(+:checked) default(shared)
    for (uint32_t k0 = 0; k0 < (1U << 16); k0++) {
        for (uint32_t k1 = 0; k1 < (1U << 16); k1++) {
            for (uint32_t k2 = 0; k2 < (1U << 16); k2++) {
                for (uint32_t k3 = 0; k3 < (1U << 16); k3++) {
                    if ((checked++ % 1000000) == 0 && omp_get_thread_num() == 0) {
                        printf("  Checked %lld keys (%.2f%%) in %ld seconds...\n",
                               checked, 100.0*checked/(1LL<<64), time(NULL)-start_time);
                    }

                    uint32_t ek0 = EK_CACHE[k0];
                    uint32_t ek1 = EK_CACHE[k1];
                    uint32_t ek2 = EK_CACHE[k2];
                    uint32_t ek3 = EK_CACHE[k3];

                    if (check_key(ek0, ek1, ek2, ek3)) {
                        printf("\n=== KEY FOUND ===\n");
                        printf("k0=0x%05X k1=0x%05X k2=0x%05X k3=0x%05X\n", k0, k1, k2, k3);
                        return 0;
                    }
                }
            }
        }
    }

    printf("\nNot found in reduced search space.\n");
    return 1;
}

