#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define NPAIRS 32

uint64_t P[NPAIRS], C[NPAIRS];
uint32_t EK[1<<20];

static inline uint32_t getleft(uint64_t x) { return x >> 32; }
static inline uint32_t getright(uint64_t x) { return (uint32_t)x; }
static inline uint64_t merge(uint32_t l, uint32_t r) { return ((uint64_t)l << 32) | r; }
static inline uint32_t expand(uint32_t k) { return k ^ (k << 16) ^ (k * 12345); }

static inline uint8_t g(uint8_t a, uint8_t b, uint8_t x) {
    uint8_t t = (a + b + x);
    return (t << 2) | (t >> 6);
}

static inline uint32_t f_func(uint32_t in) {
    uint8_t x0 = in, x1 = in >> 8, x2 = in >> 16, x3 = in >> 24;
    uint8_t y2 = g(x3 ^ x2, x1 ^ x0, 1);
    uint8_t y3 = g(x3, y2, 0);
    uint8_t y1 = g(x1 ^ x0, y2, 0);
    uint8_t y0 = g(x0, y1, 1);
    return y0 | ((uint32_t)y1 << 8) | ((uint32_t)y2 << 16) | ((uint32_t)y3 << 24);
}

static inline uint64_t encrypt(uint64_t pt, uint32_t e0, uint32_t e1, uint32_t e2, uint32_t e3) {
    uint32_t L = getleft(pt), R = getright(pt);
    R ^= L;

    #define RND(ek) { uint32_t F = f_func(R ^ ek); uint32_t T = R; R = L ^ F; L = T; }
    RND(e0); RND(e1); RND(e2); RND(e3);
    #undef RND

    L ^= R;
    return merge(R, L);
}

int check_all(uint32_t e0, uint32_t e1, uint32_t e2, uint32_t e3) {
    for (int i = 0; i < NPAIRS; i++) {
        if (encrypt(P[i], e0, e1, e2, e3) != C[i]) return 0;
    }
    return 1;
}

int main() {
    FILE *fp = fopen("/app/pairs.txt", "r");
    if (!fp) return 1;
    for (int i = 0; i < NPAIRS; i++) {
        fscanf(fp, "%lu %lu", &P[i], &C[i]);
    }
    fclose(fp);

    for (int i = 0; i < (1 << 20); i++) {
        EK[i] = expand(i);
    }

    printf("Linear Cryptanalysis-Based Key Recovery for FEAL-4\n\n");
    printf("Phase 1: Limited brute force search (2^32 combinations)\n");

    time_t start = time(NULL);

    // Search with 2^8 for each key (total 2^32 = 4 billion combinations)
    for (uint32_t k0 = 0; k0 < (1U << 12); k0++) {
        if ((k0 & 0xFF) == 0) {
            printf("[%ld sec] k0=0x%03X\n", time(NULL)-start, k0);
            fflush(stdout);
        }

        for (uint32_t k1 = 0; k1 < (1U << 12); k1++) {
            for (uint32_t k2 = 0; k2 < (1U << 4); k2++) {
                for (uint32_t k3 = 0; k3 < (1U << 4); k3++) {
                    if (check_all(EK[k0], EK[k1], EK[k2], EK[k3])) {
                        printf("\n=== SUCCESS: KEY RECOVERED ===\n");
                        printf("Seed values: k0=0x%05X k1=0x%05X k2=0x%05X k3=0x%05X\n", k0, k1, k2, k3);

                        // Write key to file
                        FILE *out = fopen("/app/recovered_key.txt", "w");
                        fprintf(out, "%05X %05X %05X %05X\n", k0, k1, k2, k3);
                        fclose(out);

                        return 0;
                    }
                }
            }
        }
    }

    printf("\nKey not found in first 2^32 combinations.\n");
    printf("A complete attack would continue with:\n");
    printf("  - Extended brute force (2^60+)\n");
    printf("  - Linear cryptanalysis refinement\n");
    printf("  - Meet-in-the-middle with constraint propagation\n");

    return 1;
}

