#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define NP 32

uint64_t P[NP], C[NP];
uint32_t EXP[1<<20];

static inline uint32_t getl(uint64_t x) { return x >> 32; }
static inline uint32_t getr(uint64_t x) { return (uint32_t)x; }
static inline uint64_t merge(uint32_t l, uint32_t r) { return ((uint64_t)l << 32) | r; }
static inline uint32_t exp(uint32_t k) { return k ^ (k << 16) ^ (k * 12345); }

static inline uint8_t g(uint8_t a, uint8_t b, uint8_t x) {
    uint8_t t = (a + b + x);
    return (t << 2) | (t >> 6);
}

static inline uint32_t f(uint32_t in) {
    uint8_t x0 = in, x1 = in >> 8, x2 = in >> 16, x3 = in >> 24;
    uint8_t y2 = g(x3 ^ x2, x1 ^ x0, 1);
    uint8_t y3 = g(x3, y2, 0);
    uint8_t y1 = g(x1 ^ x0, y2, 0);
    uint8_t y0 = g(x0, y1, 1);
    return y0 | ((uint32_t)y1 << 8) | ((uint32_t)y2 << 16) | ((uint32_t)y3 << 24);
}

static inline uint64_t enc(uint64_t pt, uint32_t e0, uint32_t e1, uint32_t e2, uint32_t e3) {
    uint32_t L = getl(pt), R = getr(pt);
    R ^= L;

    uint32_t F = f(R ^ e0);
    uint32_t T = R;
    R = L ^ F;
    L = T;

    F = f(R ^ e1);
    T = R;
    R = L ^ F;
    L = T;

    F = f(R ^ e2);
    T = R;
    R = L ^ F;
    L = T;

    F = f(R ^ e3);
    T = R;
    R = L ^ F;
    L = T;

    L ^= R;
    return merge(R, L);
}

int main() {
    FILE *fp = fopen("/app/pairs.txt", "r");
    if (!fp) return 1;
    for (int i = 0; i < NP; i++) fscanf(fp, "%lu %lu", &P[i], &C[i]);
    fclose(fp);

    for (int i = 0; i < (1 << 20); i++) EXP[i] = exp(i);

    printf("Final comprehensive brute force attack\n");
    printf("Searching full 2^80 key space with early termination...\n\n");

    time_t start = time(NULL);
    long long checked = 0;

    // Iterate all 2^20 values for each key
    for (uint32_t k0 = 0; k0 < (1U << 20); k0++) {
        if ((k0 & 0x3FF) == 0) {
            time_t now = time(NULL);
            printf("[%ld s] k0=0x%05X (%.1f%%) checks=%lld\n", now-start, k0, 100.0*k0/(1U<<20), checked);
            fflush(stdout);
        }

        uint32_t e0 = EXP[k0];

        for (uint32_t k1 = 0; k1 < (1U << 20); k1++) {
            uint32_t e1 = EXP[k1];

            for (uint32_t k2 = 0; k2 < (1U << 20); k2++) {
                uint32_t e2 = EXP[k2];

                for (uint32_t k3 = 0; k3 < (1U << 20); k3++) {
                    uint32_t e3 = EXP[k3];
                    checked++;

                    // Quick check first few pairs
                    int match = 1;
                    for (int i = 0; i < NP; i++) {
                        if (enc(P[i], e0, e1, e2, e3) != C[i]) {
                            match = 0;
                            break;
                        }
                    }

                    if (match) {
                        printf("\n*** KEY RECOVERED ***\n");
                        printf("k0=0x%05X k1=0x%05X k2=0x%05X k3=0x%05X\n", k0, k1, k2, k3);

                        FILE *out = fopen("/app/recovered_key.txt", "w");
                        fprintf(out, "%05X %05X %05X %05X\n", k0, k1, k2, k3);
                        fclose(out);

                        return 0;
                    }
                }
            }
        }
    }

    printf("\nSearch completed without finding key.\n");
    return 1;
}

